/* BroDrive — booking widget, fare calculator & UI. Rates come from assets/js/rates.js (generated by tools/build.py). */
(function () {
  'use strict';
  var B = window.BRO;
  if (!B) return;
  var R = B.rules;

  function $(s, r) { return (r || document).querySelector(s); }
  function $$(s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); }
  function inr(n) { return '₹' + Math.round(n).toLocaleString('en-IN'); }
  function pad(n) { return (n < 10 ? '0' : '') + n; }
  function dateStr(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
  function dtStr(d) { return dateStr(d) + 'T' + pad(d.getHours()) + ':' + pad(d.getMinutes()); }
  function find(list, id) { for (var i = 0; i < list.length; i++) if (list[i].id === id) return list[i]; return list[0]; }
  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function nice(d) {
    try { return d.toLocaleString('en-IN', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', hour: 'numeric', minute: '2-digit' }); }
    catch (e) { return d.toString(); }
  }

  /* ---------- Mobile nav ---------- */
  var tgl = $('.nav-toggle');
  if (tgl) {
    tgl.addEventListener('click', function () {
      var open = document.body.classList.toggle('nav-open');
      tgl.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
    $$('.site-nav a').forEach(function (a) {
      a.addEventListener('click', function () { document.body.classList.remove('nav-open'); tgl.setAttribute('aria-expanded', 'false'); });
    });
  }

  /* ---------- Fare engine (keep in sync with tools/build.py) ---------- */
  function cabFare(car, trip, km, days, pkg) {
    var lines = [], total = 0, note = '';
    if (trip === 'local') {
      var p = car.local[pkg];
      lines.push([pkg === '4h' ? '4 hrs / 40 km package' : '8 hrs / 80 km package', p]);
      total = p;
      note = 'Beyond package: ' + inr(car.km) + '/km and ' + inr(car.hr) + '/hour.';
    } else if (trip === 'oneway') {
      if (km < R.transferMaxKm) {
        lines.push(['City transfer (first ' + R.transferIncludedKm + ' km)', car.transfer]);
        var extraKm = Math.max(0, km - R.transferIncludedKm);
        if (extraKm) lines.push([extraKm + ' extra km × ' + inr(car.km), extraKm * car.km]);
        total = car.transfer + extraKm * car.km;
        note = 'Tricity & airport transfers. Waiting beyond 30 min: ' + inr(car.hr) + '/hour.';
      } else {
        var bill = Math.max(km, R.oneWayMinKm);
        lines.push([bill + ' km × ' + inr(car.km) + (km < R.oneWayMinKm ? ' (min ' + R.oneWayMinKm + ' km)' : ''), bill * car.km]);
        lines.push(['Driver allowance', car.da]);
        total = bill * car.km + car.da;
        note = 'One-way drop. Only the distance you travel is charged — no return fare.';
      }
    } else {
      var travelled = km * 2, minKm = days * R.roundMinKmPerDay, billR = Math.max(travelled, minKm);
      lines.push([billR + ' km × ' + inr(car.km) + (minKm > travelled ? ' (min ' + R.roundMinKmPerDay + ' km/day)' : ''), billR * car.km]);
      lines.push(['Driver allowance × ' + days + ' day' + (days > 1 ? 's' : ''), days * car.da]);
      total = billR * car.km + days * car.da;
      note = 'Round trip: ' + R.roundMinKmPerDay + ' km/day minimum billing. Local sightseeing at destination included in km.';
    }
    return { total: total, lines: lines, note: note };
  }

  function selfFare(car, start, end, delivery, unlimited) {
    var h = (end - start) / 36e5;
    if (!(h > 0)) return { error: 'Return time must be after pickup time.' };
    if (h < R.selfMinHours) h = R.selfMinHours;
    var full = Math.floor(h / 24), rem = h - full * 24, half = 0;
    if (rem > R.graceHours) { if (rem <= 12) half = 1; else full += 1; }
    if (!full && !half) half = 1;
    var days = full + half * 0.5;
    var rent = full * car.day + half * car.half;
    var lines = [];
    var label = (full ? full + ' day' + (full > 1 ? 's' : '') : '') + (full && half ? ' + ' : '') + (half ? '12 hrs' : '');
    lines.push([label + ' rental', rent]);
    var total = rent;
    if (unlimited) { var u = Math.round(rent * R.unlimitedPct / 100); lines.push(['Unlimited km (+' + R.unlimitedPct + '%)', u]); total += u; }
    var pct = days >= 30 ? R.disc30 : days >= 7 ? R.disc7 : 0;
    if (pct) { var d = Math.round(total * pct / 100); lines.push(['Long rental discount (' + pct + '%)', -d, 'disc']); total -= d; }
    if (delivery) {
      var fee = days >= R.freeDeliveryDays ? 0 : R.deliveryFee;
      lines.push(['Doorstep delivery & pickup' + (fee ? '' : ' (FREE)'), fee]);
      total += fee;
    }
    var freeKm = full * R.selfKmPerDay + half * R.selfKmHalf;
    return {
      total: total, lines: lines, days: days,
      note: (unlimited ? 'Unlimited km included. ' : freeKm + ' km free, then ' + inr(car.xkm) + '/km. ') +
        'Refundable security deposit ' + inr(car.dep) + '. Fuel not included (return at same level).'
    };
  }

  function renderEstimate(box, res, emptyMsg) {
    if (!res) { box.innerHTML = '<p class="est-empty">' + esc(emptyMsg) + '</p>'; return; }
    if (res.error) { box.innerHTML = '<p class="est-err">' + esc(res.error) + '</p>'; return; }
    var li = res.lines.map(function (l) {
      return '<li' + (l[2] ? ' class="' + l[2] + '"' : '') + '><span>' + esc(l[0]) + '</span><span>' + (l[1] < 0 ? '−' + inr(-l[1]) : inr(l[1])) + '</span></li>';
    }).join('');
    box.innerHTML = '<div class="est-total"><span>Estimated fare</span><strong>' + inr(res.total) + '</strong></div>' +
      '<ul class="est-lines">' + li + '</ul>' + (res.note ? '<p class="est-note">' + esc(res.note) + '</p>' : '');
  }

  function openWhatsApp(msg) {
    var url = 'https://wa.me/' + B.site.whatsapp + '?text=' + encodeURIComponent(msg);
    var w = window.open(url, '_blank', 'noopener');
    if (!w) location.href = url;
  }

  /* ---------- Booking widget ---------- */
  function initBooking(root) {
    var tabs = $$('[data-tab]', root), panes = $$('[data-pane]', root);
    function show(name) {
      tabs.forEach(function (t) { t.setAttribute('aria-selected', t.getAttribute('data-tab') === name ? 'true' : 'false'); });
      panes.forEach(function (p) { p.hidden = p.getAttribute('data-pane') !== name; });
    }
    tabs.forEach(function (t) { t.addEventListener('click', function () { show(t.getAttribute('data-tab')); }); });
    root._show = show;
    show(root.getAttribute('data-tab-default') || 'cab');

    var tomorrow = new Date(); tomorrow.setDate(tomorrow.getDate() + 1); tomorrow.setHours(10, 0, 0, 0);
    var today = dateStr(new Date());

    /* Cab pane */
    var cf = $('[data-pane="cab"]', root);
    if (cf) {
      var e = cf.elements;
      e.date.value = dateStr(tomorrow); e.date.min = today;
      e.rdate.value = dateStr(tomorrow); e.rdate.min = today;
      var box = $('.estimate', cf), other = $('[data-other]', cf);
      var calcCab = function () {
        var trip = (cf.querySelector('input[name=trip]:checked') || {}).value || 'oneway';
        $$('[data-show]', cf).forEach(function (el) { el.classList.toggle('is-hidden', el.getAttribute('data-show').split(' ').indexOf(trip) < 0); });
        var isOther = e.dest.value === 'other';
        other.classList.toggle('is-hidden', !(isOther && trip !== 'local'));
        var car = find(B.cab, e.car.value);
        if (trip === 'local') { cf._res = cabFare(car, trip, 0, 1, e.pkg.value); return renderEstimate(box, cf._res); }
        var opt = e.dest.options[e.dest.selectedIndex];
        var km = isOther ? parseFloat(e.km.value) : parseFloat(opt && opt.getAttribute('data-km'));
        if (!(km > 0)) { cf._res = null; return renderEstimate(box, null, isOther ? 'Enter the approximate one-way distance to see your fare.' : 'Choose a destination to see your fare.'); }
        var days = 1;
        if (trip === 'round') {
          var d1 = new Date(e.date.value + 'T00:00'), d2 = new Date(e.rdate.value + 'T00:00');
          if (e.rdate.value && d2 < d1) { cf._res = { error: 'Return date can’t be before the pickup date.' }; return renderEstimate(box, cf._res); }
          if (e.rdate.value && !isNaN(d2)) days = Math.round((d2 - d1) / 864e5) + 1;
        }
        cf._km = km; cf._days = days;
        cf._res = cabFare(car, trip, Math.round(km), days, e.pkg.value);
        renderEstimate(box, cf._res);
      };
      cf.addEventListener('input', calcCab);
      cf.addEventListener('change', calcCab);
      e.date.addEventListener('change', function () { if (e.rdate.value < e.date.value) e.rdate.value = e.date.value; e.rdate.min = e.date.value; calcCab(); });
      calcCab();
      root._calcCab = calcCab;
      cf.addEventListener('submit', function (ev) {
        ev.preventDefault();
        var trip = cf.querySelector('input[name=trip]:checked').value;
        var ok = true;
        [['date', !e.date.value], ['km', trip !== 'local' && e.dest.value === 'other' && !(parseFloat(e.km.value) > 0)], ['dest', trip !== 'local' && !e.dest.value]].forEach(function (c) {
          var f = e[c[0]].closest('.fld'); f.classList.toggle('invalid', c[1]); if (c[1]) ok = false;
        });
        if (!ok || (cf._res && cf._res.error)) return;
        var car = find(B.cab, e.car.value);
        var when = new Date(e.date.value + 'T' + (e.time.value || '09:00'));
        var tripName = { oneway: 'One Way', round: 'Round Trip', local: 'Local (' + (e.pkg.value === '4h' ? '4 hrs/40 km' : '8 hrs/80 km') + ')' }[trip];
        var m = ['Hi BroDrive! I want to book a cab.', '', 'Trip: ' + tripName, 'Pickup: ' + (e.from.value || '-')];
        if (trip !== 'local') m.push('Drop: ' + (e.dest.value === 'other' ? 'Other (~' + e.km.value + ' km)' : e.dest.value + ' (~' + cf._km + ' km)'));
        m.push('Date & time: ' + nice(when));
        if (trip === 'round') m.push('Return: ' + e.rdate.value + ' (' + cf._days + ' day' + (cf._days > 1 ? 's' : '') + ')');
        m.push('Car: ' + car.name + ' (' + car.models + ')');
        if (cf._res && !cf._res.error) m.push('Website estimate: ' + inr(cf._res.total) + ' + toll/parking/GST');
        if (e.name.value) m.push('Name: ' + e.name.value);
        if (e.mobile.value) m.push('Mobile: ' + e.mobile.value);
        openWhatsApp(m.join('\n'));
      });
    }

    /* Self-drive pane */
    var sf = $('[data-pane="self"]', root);
    if (sf) {
      var s = sf.elements;
      var ret = new Date(tomorrow); ret.setDate(ret.getDate() + 1);
      s.start.value = dtStr(tomorrow); s.end.value = dtStr(ret);
      s.start.min = dtStr(new Date());
      var sbox = $('.estimate', sf);
      var calcSelf = function () {
        var car = find(B.self, s.car.value);
        var a = new Date(s.start.value), b = new Date(s.end.value);
        if (isNaN(a) || isNaN(b)) { sf._res = null; return renderEstimate(sbox, null, 'Pick your dates to see the fare.'); }
        sf._res = selfFare(car, a, b, s.delivery.checked, s.unlimited.checked);
        renderEstimate(sbox, sf._res);
      };
      sf.addEventListener('input', calcSelf);
      sf.addEventListener('change', calcSelf);
      s.start.addEventListener('change', function () {
        var a = new Date(s.start.value), b = new Date(s.end.value);
        if (!isNaN(a) && (isNaN(b) || b <= a)) { var n = new Date(a); n.setDate(n.getDate() + 1); s.end.value = dtStr(n); }
        calcSelf();
      });
      calcSelf();
      sf.addEventListener('submit', function (ev) {
        ev.preventDefault();
        if (!sf._res || sf._res.error) return;
        var car = find(B.self, s.car.value);
        var m = ['Hi BroDrive! I want to book a SELF-DRIVE car in Chandigarh.', '',
          'Car: ' + car.name + ' (' + car.models + ')',
          'Pickup: ' + nice(new Date(s.start.value)),
          'Return: ' + nice(new Date(s.end.value)),
          'Doorstep delivery: ' + (s.delivery.checked ? 'Yes' : 'No, I will pick up'),
          'Unlimited km: ' + (s.unlimited.checked ? 'Yes' : 'No'),
          'Website estimate: ' + inr(sf._res.total) + ' + refundable deposit ' + inr(car.dep)];
        if (s.name.value) m.push('Name: ' + s.name.value);
        if (s.mobile.value) m.push('Mobile: ' + s.mobile.value);
        openWhatsApp(m.join('\n'));
      });
      root._calcSelf = calcSelf;
    }
  }
  var widgets = $$('[data-booking]');
  widgets.forEach(initBooking);

  /* "Book this car" buttons pre-fill the first widget on the page */
  $$('[data-pick]').forEach(function (btn) {
    btn.addEventListener('click', function (ev) {
      var w = widgets[0]; if (!w) return;
      ev.preventDefault();
      var parts = btn.getAttribute('data-pick').split(':');
      w._show(parts[0]);
      var form = $('[data-pane="' + parts[0] + '"]', w);
      if (form && form.elements.car) form.elements.car.value = parts[1];
      var dest = btn.getAttribute('data-dest');
      if (dest && form.elements.dest) form.elements.dest.value = dest;
      if (parts[0] === 'cab' && w._calcCab) w._calcCab();
      if (parts[0] === 'self' && w._calcSelf) w._calcSelf();
      w.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  });

  /* Footer year */
  $$('[data-year]').forEach(function (el) { el.textContent = new Date().getFullYear(); });
})();
